{
  "requirements": [
    {
      "obstacle_id": "o1",
      "text": "The system shall monitor steering‑torque continuously and, if no hands are detected for more than 2 seconds while Autopilot is engaged, issue an audible/visual alert and automatically disengage Autopilot."
    },
    {
      "obstacle_id": "o2",
      "text": "The system shall assess lane‑marking confidence; if confidence falls below 30 % for longer than 1 second, it shall disengage Autosteer, issue a driver alert, and maintain straight‑line travel until markings are reacquired."
    },
    {
      "obstacle_id": "o3",
      "text": "The system shall cross‑validate radar range with camera and ultrasonic data; if the discrepancy exceeds 20 % of measured distance, the radar reading shall be marked unreliable and the longitudinal controller shall revert to a conservative following distance of at least 3 seconds."
    },
    {
      "obstacle_id": "o4",
      "text": "The system shall generate a forward‑collision warning whenever any sensor (camera, radar, or ultrasonic) detects an object ahead with a time‑to‑collision ≤ 3 seconds, and shall provide redundant warning pathways to ensure notification even if one sensor fails."
    },
    {
      "obstacle_id": "o5",
      "text": "The system shall inhibit Automatic Emergency Braking while driver steering torque exceeds 0.2 Nm, unless the calculated time‑to‑collision is ≤ 1.5 seconds, in which case AEB shall be applied with a controlled torque ramp to preserve stability."
    },
    {
      "obstacle_id": "o6",
      "text": "The system shall use an interior camera to detect driver gaze; if gaze is away from the forward road for more than 3 seconds while Autopilot is active, it shall issue escalating alerts and disengage Autopilot if the driver does not re‑focus within 5 seconds."
    },
    {
      "obstacle_id": "o7",
      "text": "When Autopilot is engaged on road segments where the map identifies an intersection or crossing traffic, the system shall display a persistent on‑screen message stating that Autopilot does not control intersecting traffic and require driver acknowledgment before proceeding."
    },
    {
      "obstacle_id": "o8",
      "text": "The system shall issue a hands‑off alert within 0.5 seconds of detecting hands‑off and at least 2 seconds before any predicted lane‑departure exceeds 0.5 degrees, giving the driver sufficient time to re‑engage control."
    },
    {
      "obstacle_id": "o9",
      "text": "The system shall perform a self‑diagnostic of the steering‑torque sensor at power‑up and every 5 minutes; if a fault is detected, Autopilot shall be disabled and a driver‑only warning displayed until the sensor is repaired or reset."
    },
    {
      "obstacle_id": "o10",
      "text": "The system shall require corroboration from at least two independent sensors (e.g., radar + camera) before initiating a speed reduction for a detected lead vehicle; if only one sensor indicates a hazard, the system shall maintain current speed and issue an advisory alert."
    }
  ]
}
